      desc_pistols: "이코 라운드, 포스 바이, 그리고 매번 데저트 이글만 사는 그 친구를 위한 보조무기.",
      desc_smgs: "에임이 애매해도 무브먼트만 미쳤다면 완벽한, 난사하며 돌진하는 스프레이 머신.",
      desc_shotguns: "코너 캠퍼와 근거리 혼돈을 위한 무기. 3미터에서 원탭이 가능하다면 여기에 속합니다.",
      desc_lmgs: "맵 전체에 걸쳐 상대팀에게 당신의 존재를 알리고 싶을 때를 위한 강력한 제압 사격.",
      desc_heavy: "샷건과 기관총——모든 구매 방식에 어울리는 근접 혼돈과 풀오토 제압사격.",
      desc_rifles: "CS2의 근간——팀을 환호(혹은 폭발)하게 만드는 AK 탭, M4 스프레이, AWP 픽.",
      desc_knives: "스타일용 도구이자 이동 속도 보너스. 중고차보다 비싼 것도 있지만, 킬피드에서는 다 멋져 보입니다.",
      desc_gloves: "K/D는 다른 말을 해도 '나는 이 게임을 진지하게 한다'고 말해주는 손 코스메틱.",
